//! Proves the Rust protocol code produces the same bytes as the TypeScript code.
//! `vectors.json` was generated by running the old `tslib` code on fixed test values.

use serde_json::Value;
use teamhub_ts_proto::crypto::{derive_key_nonce, eax_decrypt, eax_encrypt, hash_password};
use teamhub_ts_proto::license::{derive_license_key, parse_license, shared_secret2, temporary_public_key};
use teamhub_ts_proto::{quicklz, Identity};

fn vectors() -> Value {
    serde_json::from_str(include_str!("vectors.json")).unwrap()
}

fn bytes(value: &Value) -> Vec<u8> {
    let text = value.as_str().unwrap();
    (0..text.len()).step_by(2).map(|i| u8::from_str_radix(&text[i..i + 2], 16).unwrap()).collect()
}

fn array16(value: &Value) -> [u8; 16] {
    bytes(value).try_into().unwrap()
}

fn array32(value: &Value) -> [u8; 32] {
    bytes(value).try_into().unwrap()
}

#[test]
fn eax_matches() {
    let v = vectors();
    let (key, nonce, header) = (array16(&v["eaxKey"]), array16(&v["eaxNonce"]), bytes(&v["eaxHeader"]));
    for case in v["eax"].as_array().unwrap() {
        let plain = bytes(&case["plain"]);
        let (ciphertext, mac) = eax_encrypt(&key, &nonce, &header, &plain);
        assert_eq!(ciphertext, bytes(&case["ciphertext"]), "ciphertext of {} bytes", plain.len());
        assert_eq!(mac.to_vec(), bytes(&case["mac"]), "mac of {} bytes", plain.len());
        assert_eq!(eax_decrypt(&key, &nonce, &header, &ciphertext, &mac).unwrap(), plain);
    }
}

#[test]
fn packet_keys_match() {
    for case in vectors()["derive"].as_array().unwrap() {
        let (key, nonce) = derive_key_nonce(
            case["fromServer"].as_bool().unwrap(),
            case["id"].as_u64().unwrap() as u16,
            case["gen"].as_u64().unwrap() as u32,
            case["type"].as_u64().unwrap() as u8,
            &bytes(&case["iv"]),
        );
        assert_eq!(key.to_vec(), bytes(&case["key"]));
        assert_eq!(nonce.to_vec(), bytes(&case["nonce"]));
    }
}

#[test]
fn identity_matches() {
    let v = vectors();
    let case = &v["identity"];
    let scalar = case["scalar"].as_str().unwrap();
    let identity = Identity::from_stored(scalar, "0").unwrap();
    assert_eq!(identity.public_key_string, case["publicKeyString"].as_str().unwrap());
    assert_eq!(identity.uid, case["uid"].as_str().unwrap());
    assert_eq!(identity.private_scalar(), scalar);

    for level in case["levels"].as_array().unwrap() {
        let offset = level["offset"].as_u64().unwrap().to_string();
        let at_offset = Identity::from_stored(scalar, &offset).unwrap();
        assert_eq!(u64::from(at_offset.security_level()), level["level"].as_u64().unwrap(), "offset {offset}");
    }

    use base64::{engine::general_purpose::STANDARD, Engine};
    let peer = STANDARD.decode(case["peerPublicKeyString"].as_str().unwrap()).unwrap();
    assert_eq!(identity.shared_secret(&peer).unwrap().to_vec(), bytes(&case["sharedSecret"]));
    let peer_identity = Identity::from_stored(case["peerScalar"].as_str().unwrap(), "0").unwrap();
    assert_eq!(peer_identity.public_key_string, case["peerPublicKeyString"].as_str().unwrap());
}

#[test]
fn license_chain_matches() {
    let v = vectors();
    let case = &v["license"];
    let blocks = parse_license(&bytes(&case["bytes"])).unwrap();
    assert_eq!(blocks.len(), 2);
    let derived = derive_license_key(&blocks).unwrap();
    assert_eq!(derived.to_vec(), bytes(&case["derived"]));
    let private = array32(&case["tempPrivate"]);
    assert_eq!(temporary_public_key(&private).to_vec(), bytes(&case["tempPublic"]));
    assert_eq!(shared_secret2(&derived, &private).unwrap().to_vec(), bytes(&case["shared"]));
}

#[test]
fn quicklz_matches() {
    for case in vectors()["quicklz"].as_array().unwrap() {
        assert_eq!(quicklz::decompress(&bytes(&case["input"])).unwrap(), bytes(&case["output"]));
    }
}

#[test]
fn password_hash_matches() {
    let v = vectors();
    assert_eq!(hash_password(v["password"]["input"].as_str().unwrap()), v["password"]["hash"].as_str().unwrap());
    assert_eq!(hash_password(""), "");
}
